//! Cross-language canonical-identifier parity against the Python kernel.
//!
//! Reads the fixture generated by `tests/generate_canonical_parity.py` and
//! recomputes every identifier with the Rust kernel. The generator uses the
//! Python higher-operad kernel and the current operad catalog.
//!
//! This is the test that makes the port trustworthy: a one-byte divergence in
//! key ordering, separators, escaping, field order, or domain string would
//! silently reissue every identifier the estate stores, and it would be caught
//! here rather than in production data.
//!
//! AuthorityEffect: None.

use std::path::PathBuf;

use core_operad_theory::kernel::canonical::canonical_id;
use core_operad_theory::kernel::observer::ObserverDeclaration;
use core_operad_theory::kernel::model::{
    AuthorityEffect, ColourSpec, InvocationGrade, OperandRef, OperationSpec, OperationSpecInput,
    PortSpec,
};
use serde_json::Value;

fn fixture() -> Value {
    // tests/ -> crate root -> crates_rs -> engine -> repo root
    let path: PathBuf = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../tests/core_operad_theory")
        .join("fixtures")
        .join("canonical_parity.json");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|error| {
        panic!(
            "parity fixture missing at {}: {error}. Regenerate it by running \
             engine/crates_rs/tests/core_operad_theory/generate_canonical_parity.py --write",
            path.display()
        )
    });
    serde_json::from_str(&text).expect("parity fixture must be valid JSON")
}

fn strings(value: &Value) -> Vec<String> {
    value
        .as_array()
        .expect("expected an array")
        .iter()
        .map(|item| item.as_str().expect("expected a string").to_owned())
        .collect()
}

fn operation_spec(
    operation_id: &str,
    source_colours: &[String],
    target_colour: &str,
    executor_digest: &str,
) -> OperationSpec {
    let input_ports = source_colours
        .iter()
        .enumerate()
        .map(|(index, colour)| {
            PortSpec::new(&format!("in_{index}"), colour, "any").expect("port must build")
        })
        .collect::<Vec<_>>();

    OperationSpec::new(OperationSpecInput {
        operation_id,
        version: "v1",
        input_ports,
        output_port: PortSpec::new("out", target_colour, "any").expect("output port must build"),
        executor_ref: operation_id,
        executor_digest,
        tool_refs: vec![],
        effects: vec![],
        invocation_grade: InvocationGrade::Discipline,
        authority_effect: AuthorityEffect::None,
        authority_ceiling: AuthorityEffect::None,
    })
    .expect("operation spec must build")
}

#[test]
fn every_operation_identifier_matches_python() {
    let fixture = fixture();
    let operations = fixture["operations"].as_array().expect("operations array");
    assert!(!operations.is_empty(), "fixture operations cannot be empty");
    assert!(fixture["skipped"].as_array().expect("explicit refusal array").is_empty(),
        "all current catalog entries must have cross-language encoding coverage");

    let mut checked = 0usize;
    for case in operations {
        let operation_id = case["operation_id"].as_str().expect("operation_id");
        let spec = operation_spec(
            operation_id,
            &strings(&case["source_colours"]),
            case["target_colour"].as_str().expect("target_colour"),
            case["executor_digest"].as_str().expect("executor_digest"),
        );

        assert_eq!(
            spec.canonical_id().expect("canonical id"),
            case["canonical_id"].as_str().expect("canonical_id"),
            "canonical id diverged from Python for operation {operation_id}"
        );
        assert_eq!(spec.key(), case["key"].as_str().expect("key"), "key for {operation_id}");
        checked += 1;
    }
    assert_eq!(checked, operations.len());
}

#[test]
fn every_colour_identifier_matches_python() {
    let fixture = fixture();
    let colours = fixture["colours"].as_array().expect("colours array");
    assert_eq!(colours.len(), 10, "the estate admits exactly ten colours");

    for case in colours {
        let colour_id = case["colour_id"].as_str().expect("colour_id");
        let spec = ColourSpec::new(
            colour_id,
            "estate",
            "any",
            case["schema_digest"].as_str().expect("schema_digest"),
            "estate.validator",
            case["validator_digest"].as_str().expect("validator_digest"),
            "v1",
        )
        .expect("colour spec must build");

        assert_eq!(
            spec.canonical_id().expect("canonical id"),
            case["canonical_id"].as_str().expect("canonical_id"),
            "canonical id diverged from Python for colour {colour_id}"
        );
    }
}

#[test]
fn operand_ref_identifier_matches_python() {
    let fixture = fixture();
    let case = &fixture["operand_ref"];
    let operand = OperandRef::new(
        case["artifact_digest"].as_str().expect("artifact_digest"),
        case["colour_id"].as_str().expect("colour_id"),
        case["schema_ref"].as_str().expect("schema_ref"),
        case["admission_receipt_ref"].as_str().expect("admission_receipt_ref"),
        case["provenance_root"].as_str().expect("provenance_root"),
    )
    .expect("operand ref must build");

    assert_eq!(
        operand.canonical_id().expect("canonical id"),
        case["canonical_id"].as_str().expect("canonical_id")
    );
}

#[test]
fn every_raw_envelope_identifier_matches_python() {
    let fixture = fixture();
    for case in fixture["envelopes"].as_array().expect("envelopes array") {
        let name = case["name"].as_str().expect("name");
        let computed = canonical_id(
            case["domain"].as_str().expect("domain"),
            &case["payload"],
        )
        .expect("canonical id");

        assert_eq!(
            computed,
            case["canonical_id"].as_str().expect("canonical_id"),
            "canonical id diverged from Python for envelope case {name}"
        );
    }
}

#[test]
fn identifiers_are_distinct_across_the_catalog() {
    let fixture = fixture();
    let mut seen = std::collections::BTreeSet::new();
    for case in fixture["operations"].as_array().expect("operations array") {
        let id = case["canonical_id"].as_str().expect("canonical_id").to_owned();
        assert!(seen.insert(id.clone()), "duplicate canonical id in catalog: {id}");
    }
}

#[test]
fn every_observer_id_matches_python() {
    // Two atlas entries are comparable only when their observer ids agree, so
    // an id computed on the Python side and one computed here must be the same
    // string or cross-language collision detection is meaningless.
    let fixture = fixture();
    let observers = fixture["observers"].as_array().expect("observers array");
    assert!(!observers.is_empty());

    for case in observers {
        let name = case["name"].as_str().expect("name");
        let declaration = &case["declaration"];

        let observer = ObserverDeclaration::new(
            declaration["regime"].as_str().expect("regime"),
            declaration["comparison_relation"].as_str().expect("comparison_relation"),
            &strings(&declaration["allowed_lifts_and_gauges"]),
            declaration["defect_definition"].as_str().expect("defect_definition"),
            declaration["terminal_rule"].as_str().expect("terminal_rule"),
        )
        .expect("observer must build");

        assert_eq!(
            observer.observer_id().expect("observer id"),
            case["observer_id"].as_str().expect("observer_id"),
            "observer id diverged from Python for case {name}"
        );
    }
}

#[test]
fn observer_ids_are_distinct_across_rule_cards() {
    let fixture = fixture();
    let mut seen = std::collections::BTreeSet::new();
    for case in fixture["observers"].as_array().expect("observers array") {
        let id = case["observer_id"].as_str().expect("observer_id").to_owned();
        assert!(seen.insert(id), "two distinct rule cards share an observer id");
    }
}

